    wire a = d ^ c;
    wire b = ~(d & c);
    wire [3:0] mux0_in = {a, b, 1'b0, 1'b1};
    wire [3:0] mux1_in = {a, b, 1'b1, 1'b1};
    wire [3:0] mux2_in = {a, b, 1'b1, 1'b0};
    wire [3:0] mux3_in = {a, b, 1'b0, 1'b0};
